class Solution {
    public int minDistance(String word1, String word2) {
        return distance(word1, word2, 0, 0);
    }

    private int distance(String first, String second, int i, int j) {
        if (i == first.length()) return second.length() - j;
        if (j == second.length()) return first.length() - i;
        if (first.charAt(i) == second.charAt(j)) {
            return distance(first, second, i + 1, j + 1);
        }
        int insert = distance(first, second, i, j + 1);
        int delete = distance(first, second, i + 1, j);
        int replace = distance(first, second, i + 1, j + 1);
        return 1 + Math.min(insert, Math.min(delete, replace));
    }
}

